import{_ as a,a0 as n,w as s,s as d,ao as u,I as e,x as o,a1 as i,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Ciao：雲集成高級編排器 | LCTT x X-CMD","titleTemplate":false,"description":"Ciao：雲集成高級編排器 | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ciao：雲集成高級編排器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ciao：雲集成高級編排器 | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/2017 Cloud Integrated Advanced Orchestrator","title":"Ciao：雲集成高級編排器","tag":"201710","desc":""},"relativePath":"201710/2017 Cloud Integrated Advanced Orchestrator.md","filePath":"[post].md"}'),p={name:"201710/2017 Cloud Integrated Advanced Orchestrator.md"};function C(g,t,m,f,T,x){const l=n("Link");return s(),d("div",null,[t[19]||(t[19]=u('<h1 id="ciao-雲集成高級編排器" tabindex="-1">Ciao：雲集成高級編排器 <a class="header-anchor" href="#ciao-雲集成高級編排器" aria-label="Permalink to “Ciao：雲集成高級編排器”">​</a></h1><p><ruby>雲集成高級編排器<rt>Cloud Integrated Advanced Orchestrator</rt></ruby> （Ciao） 是一個新的負載調度程序，用來解決當前雲操作系統項目的侷限性。Ciao 提供了一個輕量級，完全基於 TLS 的最小配置。它是 工作量無關的、易於更新、具有優化速度的調度程序，目前已針對 OpenStack 進行了優化。</p><p>其設計決策和創新方法在對安全性、可擴展性、可用性和可部署性的要求下進行：</p><ul><li><strong>可擴展性：</strong> 初始設計目標是伸縮超過 5,000 個節點。因此，調度器架構用新的形式實現： <ul><li>在 ciao 中，決策制定是去中心化的。它基於拉取模型，允許計算節點從調度代理請求作業。調度程序總能知道啓動器的容量，而不要求進行數據更新，並且將調度決策時間保持在最小。啓動器異步向調度程序發送容量。</li><li>持久化狀態跟蹤與調度程序決策制定相分離，它讓調度程序保持輕量級。這種分離增加了可靠性、可擴展性和性能。結果是調度程序讓出了權限並且這不是瓶頸。</li></ul></li><li><strong>可用性：</strong> 虛擬機、容器和裸機集成到一個調度器中。所有的負載都被視為平等公民。為了更易於使用，網絡通過一個組件間最小化的異步協議進行簡化，只需要最少的配置。Ciao 還包括一個新的、簡單的 UI。所有的這些功能都集成到一起來簡化安裝、配置、維護和操作。</li><li><strong>輕鬆部署：</strong> 升級應該是預期操作，而不是例外情況。這種新的去中心化狀態的體系結構能夠無縫升級。為了確保基礎設施（例如 OpenStack）始終是最新的，它實現了持續集成/持續交付（CI/CD）模型。Ciao 的設計使得它可以立即殺死任何 Ciao 組件，更換它，並重新啓動它，對可用性影響最小。</li><li><strong>安全性是必需的：</strong> 與調度程序的連接總是加密的：默認情況下 SSL 是打開的，而不是關閉的。加密是從端到端：所有外部連接都需要 HTTPS，組件之間的內部通信是基於 TLS 的。網絡支持的一體化保障了租户分離。</li></ul><p>初步結果證明是顯著的：在 65 秒內啓動一萬個 Docker 容器和五千個虛擬機。進一步優化還在進行。</p>',5)),e("ul",null,[e("li",null,[t[1]||(t[1]=o("文檔：",-1)),i(l,{href:"https://clearlinux.org/documentation/ciao/ciao.html"},{default:r(()=>[...t[0]||(t[0]=[o("https://clearlinux.org/documentation/ciao/ciao.html",-1)])]),_:1})]),e("li",null,[t[3]||(t[3]=o("Github 鏈接： ",-1)),i(l,{href:"https://github.com/01org/ciao"},{default:r(()=>[...t[2]||(t[2]=[o("https://github.com/01org/ciao(link is external)",-1)])]),_:1})]),e("li",null,[t[5]||(t[5]=o("郵件列表鏈接： ",-1)),i(l,{href:"https://lists.clearlinux.org/mailman/listinfo/ciao-devel"},{default:r(()=>[...t[4]||(t[4]=[o("https://lists.clearlinux.org/mailman/listinfo/ciao-devel",-1)])]),_:1})])]),t[20]||(t[20]=e("hr",null,null,-1)),e("p",null,[t[7]||(t[7]=o("via: ",-1)),i(l,{href:"https://clearlinux.org/ciao"},{default:r(()=>[...t[6]||(t[6]=[o("https://clearlinux.org/ciao",-1)])]),_:1})]),e("p",null,[t[11]||(t[11]=o("作者：",-1)),i(l,{href:"https://clearlinux.org/ciao"},{default:r(()=>[...t[8]||(t[8]=[o("ciao",-1)])]),_:1}),t[12]||(t[12]=o(" 譯者：",-1)),i(l,{href:"https://github.com/geekpi"},{default:r(()=>[...t[9]||(t[9]=[o("geekpi",-1)])]),_:1}),t[13]||(t[13]=o(" 校對：",-1)),i(l,{href:"https://github.com/wxy"},{default:r(()=>[...t[10]||(t[10]=[o("wxy",-1)])]),_:1})]),e("p",null,[t[16]||(t[16]=o("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[14]||(t[14]=[o("LCTT",-1)])]),_:1}),t[17]||(t[17]=o(" 原創編譯，",-1)),i(l,{href:"https://linux.cn/"},{default:r(()=>[...t[15]||(t[15]=[o("Linux中國",-1)])]),_:1}),t[18]||(t[18]=o(" 榮譽推出",-1))])])}const v=a(p,[["render",C]]);export{k as __pageData,v as default};
